"use client"

import * as React from "react"

import { createViewerResource } from "@/lib/viewer-resource"
import { useIsClient } from "@/components/ui/use-is-client"
import { ViewerErrorBoundary } from "@/components/ui/viewer-error"

import { XlsxViewerFallback } from "./xlsx-viewer-chrome"
import { XlsxViewerSession } from "./xlsx-viewer-session"
import type {
  XlsxResourceViewerProps,
  XlsxViewerHandle,
  XlsxViewerProps,
} from "./xlsx-viewer-types"

export type {
  XlsxCellRef,
  XlsxDocumentSource,
  XlsxResourceViewerProps,
  XlsxViewerHandle,
  XlsxViewerProps,
} from "./xlsx-viewer-types"

export const XlsxViewer = React.forwardRef<XlsxViewerHandle, XlsxViewerProps>(
  function XlsxViewer(props, ref) {
    const { source, ...resourceProps } = props
    const resource = React.useMemo(() => createViewerResource(source), [source])
    return (
      <XlsxResourceViewer {...resourceProps} ref={ref} resource={resource} />
    )
  }
)

export const XlsxResourceViewer = React.forwardRef<
  XlsxViewerHandle,
  XlsxResourceViewerProps
>(function XlsxResourceViewer(props, ref) {
  const isClient = useIsClient()
  const resource = props.resource
  if (!isClient) {
    return (
      <XlsxViewerFallback
        className={props.className}
        fallbackSheetTabs={props.fallbackSheetTabs}
        toolbar={props.toolbar}
        bare={props.bare}
        slots={props.slots}
      />
    )
  }
  return (
    <ViewerErrorBoundary
      className={props.className}
      download={resource.originalDownload}
      format="xlsx"
      resetKey={resource.keys.resource}
      sourceKind={resource.sourceKind}
    >
      <React.Suspense
        fallback={
          <XlsxViewerFallback
            className={props.className}
            fallbackSheetTabs={props.fallbackSheetTabs}
            toolbar={props.toolbar}
            bare={props.bare}
            slots={props.slots}
          />
        }
      >
        <XlsxViewerSession
          key={resource.keys.resource}
          {...props}
          forwardedRef={ref}
          resource={resource}
        />
      </React.Suspense>
    </ViewerErrorBoundary>
  )
})

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Skeleton } from "@/components/ui/skeleton"
import { XlsxGridSkeleton } from "@/components/ui/xlsx-grid"
import { XLSX_SHEET_TABS_HEIGHT_PX } from "@/components/ui/xlsx-sheet-tabs"
import {
  XLSX_TOOLBAR_HEIGHT_PX,
  XlsxToolbarSkeleton,
} from "@/components/ui/xlsx-toolbar"

import type { XlsxViewerSlots } from "./xlsx-viewer-types"

export function XlsxViewerFrame({
  className,
  bare,
  children,
}: {
  className?: string
  bare: boolean
  children: React.ReactNode
}) {
  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="xlsx-viewer"
    >
      {children}
    </div>
  )
}

export function XlsxViewerBody({
  children,
  fallbackSheetTabs,
  slots,
  toolbar,
}: {
  children: React.ReactNode
  fallbackSheetTabs: boolean
  slots?: XlsxViewerSlots
  toolbar: boolean
}) {
  return (
    <div
      className={cn(
        "relative flex min-h-0",
        fallbackSheetTabs ? "flex-none" : "flex-1"
      )}
      style={
        fallbackSheetTabs
          ? {
              height: `calc(100% - ${
                XLSX_SHEET_TABS_HEIGHT_PX +
                (toolbar ? XLSX_TOOLBAR_HEIGHT_PX : 0)
              }px)`,
            }
          : undefined
      }
    >
      {slots?.left ? (
        <div data-slot="xlsx-viewer-left" className="flex-shrink-0">
          {slots.left}
        </div>
      ) : null}
      <div className="flex min-h-0 min-w-0 flex-1 flex-col">
        {slots?.top ? <div data-slot="xlsx-viewer-top">{slots.top}</div> : null}
        {children}
        {slots?.bottom ? (
          <div data-slot="xlsx-viewer-bottom">{slots.bottom}</div>
        ) : null}
      </div>
      {slots?.right ? (
        <div data-slot="xlsx-viewer-right" className="flex-shrink-0">
          {slots.right}
        </div>
      ) : null}
      {slots?.overlay ? (
        <div
          data-slot="xlsx-viewer-overlay"
          className="pointer-events-none absolute inset-0 z-20"
        >
          {slots.overlay}
        </div>
      ) : null}
    </div>
  )
}

export function XlsxGridColumn({ children }: { children: React.ReactNode }) {
  return <div className="flex min-h-0 min-w-0 flex-1 flex-col">{children}</div>
}

export function XlsxViewerFallback({
  className,
  fallbackSheetTabs = false,
  toolbar = true,
  bare = false,
  slots,
}: {
  className?: string
  fallbackSheetTabs?: boolean
  toolbar?: boolean
  bare?: boolean
  slots?: XlsxViewerSlots
}) {
  return (
    <XlsxViewerFrame className={className} bare={bare}>
      {toolbar ? <XlsxToolbarSkeleton /> : null}
      <XlsxViewerBody
        toolbar={toolbar}
        fallbackSheetTabs={fallbackSheetTabs}
        slots={slots}
      >
        <XlsxGridSkeleton />
      </XlsxViewerBody>
      {fallbackSheetTabs ? <XlsxSheetTabsSkeleton /> : null}
    </XlsxViewerFrame>
  )
}

export function XlsxSheetTabsSkeleton() {
  return (
    <div
      aria-hidden
      className="flex flex-shrink-0 items-stretch gap-0.5 overflow-hidden border-t bg-card px-1.5 py-1"
      data-slot="xlsx-viewer-tabs-skeleton"
      style={{ height: XLSX_SHEET_TABS_HEIGHT_PX }}
    >
      {[96, 144, 136, 128].map((width, index) => (
        <div
          key={index}
          className="flex h-[24px] flex-shrink-0 items-center rounded-md px-2.5"
          style={{ width }}
        >
          <Skeleton className="h-3 w-full" />
        </div>
      ))}
    </div>
  )
}

import {
  isResourceError,
  isViewerFormatError,
  ViewerFormatError,
  type ViewerFormatErrorMapperOptions,
} from "@/lib/viewer-errors"
import type { ViewerContentBytes } from "@/lib/viewer-resource"
import {
  buildXlsxSourceFromCompact,
  XlsxSourceCache,
  type CompactSheet,
  type XlsxSource,
} from "@/lib/xlsx-workbook"
import {
  type XlsxWorkerRequest,
  type XlsxWorkerResponse,
} from "@/lib/xlsx-worker-protocol"

const sourceCache = new XlsxSourceCache({ maxEntries: 4 })

export function getXlsxSource(
  content: ViewerContentBytes
): Promise<XlsxSource> {
  return sourceCache.get(content.key, () => buildXlsxSource(content))
}

async function buildXlsxSource(
  content: ViewerContentBytes
): Promise<XlsxSource> {
  try {
    const buffer = await content.readBytes()
    return buildXlsxSourceFromCompact(await parseWorkbookInWorker(buffer))
  } catch (error) {
    if (isResourceError(error)) throw error
    throw toXlsxFormatError(error, {
      kind: "parse_failed",
      message: "Failed to parse spreadsheet.",
    })
  }
}

function toXlsxFormatError(
  error: unknown,
  options: ViewerFormatErrorMapperOptions
): ViewerFormatError {
  if (isViewerFormatError(error)) return error
  return new ViewerFormatError({
    format: "xlsx",
    kind: options.kind,
    message: options.message,
    cause: error,
  })
}

function parseWorkbookInWorker(buffer: ArrayBuffer): Promise<CompactSheet[]> {
  return new Promise((resolve, reject) => {
    if (typeof Worker === "undefined") {
      reject(
        toXlsxFormatError(undefined, {
          kind: "worker_failed",
          message: "Web Workers are unavailable in this environment.",
        })
      )
      return
    }

    const worker = new Worker(
      new URL("./xlsx-viewer.worker", import.meta.url),
      { type: "module" }
    )
    worker.onmessage = (event: MessageEvent<unknown>) => {
      worker.terminate()
      const response = parseXlsxWorkerResponse(event.data)
      if (!response) {
        reject(
          toXlsxFormatError(undefined, {
            kind: "parse_failed",
            message: "Spreadsheet worker returned an invalid response.",
          })
        )
        return
      }
      if (response.type === "workbook") {
        resolve(response.sheets)
      } else {
        reject(
          toXlsxFormatError(undefined, {
            kind: "parse_failed",
            message: response.message || "Failed to parse spreadsheet.",
          })
        )
      }
    }
    worker.onerror = (event) => {
      worker.terminate()
      reject(
        toXlsxFormatError(event, {
          kind: "worker_failed",
          message: event.message || "Spreadsheet worker failed.",
        })
      )
    }
    const request: XlsxWorkerRequest = { type: "parse_workbook", buffer }
    worker.postMessage(request, [buffer])
  })
}

function parseXlsxWorkerResponse(value: unknown): XlsxWorkerResponse | null {
  if (value == null || typeof value !== "object") return null
  const response = value as Partial<XlsxWorkerResponse>
  if (response.type === "workbook") {
    return Array.isArray(response.sheets)
      ? ({
          type: "workbook",
          sheets: response.sheets,
        } satisfies XlsxWorkerResponse)
      : null
  }
  if (response.type === "error") {
    return {
      type: "error",
      code: "parse_failed",
      message:
        typeof response.message === "string"
          ? response.message
          : "Failed to parse spreadsheet.",
    }
  }
  return null
}

"use client"

import * as React from "react"

import type { ViewerResource } from "@/lib/viewer-resource"
import { XlsxSheetTabs } from "@/components/ui/xlsx-sheet-tabs"
import { XlsxToolbar } from "@/components/ui/xlsx-toolbar"

import {
  XlsxGridColumn,
  XlsxSheetTabsSkeleton,
  XlsxViewerBody,
  XlsxViewerFrame,
} from "./xlsx-viewer-chrome"
import { useXlsxDownloadActions } from "./xlsx-viewer-download"
import { useXlsxScale } from "./xlsx-viewer-scale"
import { getXlsxSource } from "./xlsx-viewer-resource"
import { useXlsxScrollController } from "./xlsx-viewer-scroll"
import { XlsxViewerSheet, XlsxViewerSheetSkeleton } from "./xlsx-viewer-sheet"
import { useXlsxSheetState } from "./xlsx-viewer-sheet-state"
import type { XlsxViewerHandle, XlsxViewerProps } from "./xlsx-viewer-types"

export function XlsxViewerSession({
  resource,
  className,
  toolbar = true,
  defaultSheetIndex = 0,
  onSheetChange,
  fallbackSheetTabs = false,
  bare = false,
  slots,
  activeCell,
  isolateStyles = false,
  forwardedRef,
}: Omit<XlsxViewerProps, "source"> & {
  resource: ViewerResource
  forwardedRef?: React.ForwardedRef<XlsxViewerHandle>
}) {
  const viewportElementRef = React.useRef<HTMLDivElement | null>(null)
  const content = resource.content
  const sourcePromise = React.useMemo(() => getXlsxSource(content), [content])
  const {
    activeSheetIndex,
    activeSheet,
    sheets,
    isReady,
    reportSource,
    selectSheet,
    activateSheet,
  } = useXlsxSheetState({ defaultSheetIndex, onSheetChange })
  const { scale, zoomOut, zoomIn, resetZoom } = useXlsxScale()
  const { scrollRequest, scrollToCell } = useXlsxScrollController({
    activeSheetIndex,
    sheets,
    activateSheet,
  })

  React.useImperativeHandle(
    forwardedRef ?? null,
    () => ({
      scrollToCell,
      getViewportElement: () => viewportElementRef.current,
    }),
    [scrollToCell]
  )

  const isReservingFallbackSheetTabs = fallbackSheetTabs && !sheets
  const downloadActions = useXlsxDownloadActions({
    resource,
    activeSheet,
    activeSheetIndex,
    content,
    sheets,
  })

  return (
    <XlsxViewerFrame className={className} bare={bare}>
      {toolbar ? (
        <XlsxToolbar
          downloadActions={downloadActions}
          sheet={activeSheet ?? undefined}
          isReady={isReady}
          scale={scale}
          onZoomOut={zoomOut}
          onZoomIn={zoomIn}
          onResetZoom={resetZoom}
        />
      ) : null}

      <XlsxViewerBody
        toolbar={toolbar}
        fallbackSheetTabs={isReservingFallbackSheetTabs}
        slots={slots}
      >
        <XlsxGridColumn>
          <React.Suspense fallback={<XlsxViewerSheetSkeleton />}>
            <XlsxViewerSheet
              sourcePromise={sourcePromise}
              activeSheetIndex={activeSheetIndex}
              scale={scale}
              onReportSource={reportSource}
              activeCell={activeCell}
              scrollRequest={scrollRequest}
              isolateStyles={isolateStyles}
              viewportRef={viewportElementRef}
            />
          </React.Suspense>
        </XlsxGridColumn>
      </XlsxViewerBody>

      {sheets ? (
        <XlsxSheetTabs
          sheets={sheets}
          activeSheetIndex={activeSheetIndex}
          onSelectSheet={selectSheet}
        />
      ) : fallbackSheetTabs ? (
        <XlsxSheetTabsSkeleton />
      ) : null}
    </XlsxViewerFrame>
  )
}

import type { ViewerResource } from "@/lib/viewer-resource"
import type { BlobViewerSource, UrlViewerSource } from "@/lib/viewer-source"

import type { ViewerSlots } from "./viewer-slots"
import type { PublicXlsxCellRef } from "./xlsx-viewer-scroll"

export type XlsxDocumentSource = UrlViewerSource | BlobViewerSource

export type XlsxViewerSlots = ViewerSlots

export interface XlsxViewerProps {
  /** Canonical spreadsheet source. */
  source: XlsxDocumentSource
  className?: string
  toolbar?: boolean
  /** Sheet shown first. Defaults to 0. */
  defaultSheetIndex?: number
  /** Fired with the active sheet index on tab switch and imperative sheet changes. */
  onSheetChange?: (index: number) => void
  /** Reserve the workbook tab bar while metadata loads. Use for known multi-sheet files. */
  fallbackSheetTabs?: boolean
  /** Drop the outer border/rounded/background so the viewer fills its container. */
  bare?: boolean
  /** Document-attached chrome mounted around the grid surface. */
  slots?: XlsxViewerSlots
  /** Public compatibility coordinates: 0-based row + column on `sheet`. */
  activeCell?: XlsxCellRef | null
  /**
   * Render the scrolling grid inside a shadow root, isolating it from host page
   * style invalidation while preserving inherited theme variables.
   */
  isolateStyles?: boolean
}

export type XlsxResourceViewerProps = Omit<XlsxViewerProps, "source"> & {
  resource: ViewerResource
}

export type XlsxCellRef = PublicXlsxCellRef

export interface XlsxViewerHandle {
  scrollToCell: (
    sheet: number,
    row: number,
    col: number,
    options?: { behavior?: ScrollBehavior }
  ) => void
  getViewportElement: () => HTMLDivElement | null
}

import * as React from "react"

import type { ViewerDownloadAction } from "@/lib/viewer-download"
import type {
  ViewerResource,
  ViewerResourceContent,
} from "@/lib/viewer-resource"
import type { XlsxSource } from "@/lib/xlsx-workbook"
import { type XlsxSheetMeta, xlsxColumnLabel } from "@/lib/xlsx-workbook"

import { serializeCsvTable } from "./csv-viewer-download"
import { getXlsxSource } from "./xlsx-viewer-resource"

const CSV_DIALECT = { delimiter: ",", hasHeader: true } as const
const MAX_DENSE_CSV_EXPORT_CELLS = 1_000_000

export function createXlsxSheetCsvExportAction({
  fileName,
  sheetIndex,
  getSource,
}: {
  fileName: string
  sheetIndex: number
  getSource: () => Promise<XlsxSource>
}): ViewerDownloadAction {
  return {
    id: "xlsx-export-sheet",
    label: "Export sheet",
    fileName,
    origin: "derived",
    getPayload: async ({ signal } = {}) => {
      throwIfAborted(signal)
      const source = await getSource()
      throwIfAborted(signal)
      return {
        kind: "text",
        text: serializeXlsxSheetAsCsv({ source, sheetIndex, signal }),
        mimeType: "text/csv;charset=utf-8",
      }
    },
  }
}

export function xlsxSheetCsvFileName({
  fileName,
  sheetName,
  sheetCount,
}: {
  fileName: string
  sheetName?: string
  sheetCount?: number
}) {
  const baseName = sanitizeFileNamePart(
    fileName.replace(/\.[^.\\/]+$/, "") || "spreadsheet",
    "spreadsheet"
  )
  if (!sheetName || sheetCount == null || sheetCount <= 1) {
    return `${baseName}.csv`
  }
  return `${baseName}.${sanitizeFileNamePart(sheetName)}.csv`
}

export function useXlsxDownloadActions({
  resource,
  activeSheet,
  activeSheetIndex,
  sheets,
  content,
}: {
  resource: ViewerResource
  activeSheet: XlsxSheetMeta | null
  activeSheetIndex: number
  sheets: XlsxSheetMeta[] | null
  content: ViewerResourceContent
}) {
  return React.useMemo(() => {
    const originalDownloadAction = {
      ...resource.originalDownload,
      label: activeSheet ? "Download original" : "Download",
    }
    if (!activeSheet || !sheets) return [originalDownloadAction]
    return [
      originalDownloadAction,
      createXlsxSheetCsvExportAction({
        fileName: xlsxSheetCsvFileName({
          fileName: resource.fileName,
          sheetName: activeSheet.name,
          sheetCount: sheets.length,
        }),
        sheetIndex: activeSheetIndex,
        getSource: () => getXlsxSource(content),
      }),
    ]
  }, [
    activeSheet,
    activeSheetIndex,
    content,
    resource.fileName,
    resource.originalDownload,
    sheets,
  ])
}

function serializeXlsxSheetAsCsv({
  source,
  sheetIndex,
  signal,
}: {
  source: XlsxSource
  sheetIndex: number
  signal?: AbortSignal
}) {
  const sheet = source.sheets[sheetIndex]
  if (!sheet) return ""
  const rowCount = normalizeSheetDimension(sheet.rowCount)
  const columnCount = normalizeSheetDimension(sheet.columnCount)
  if (rowCount === 0 || columnCount === 0) return ""
  if (rowCount * columnCount > MAX_DENSE_CSV_EXPORT_CELLS) return ""

  const columns = Array.from({ length: columnCount }, (_, columnIndex) =>
    xlsxColumnLabel(columnIndex)
  )
  const sourceRows = Array.from({ length: rowCount }, (_, rowIndex) => {
    throwIfAborted(signal)
    return Array.from({ length: columnCount }, (_, columnIndex) => {
      const text = source.getCell(sheetIndex, rowIndex, columnIndex).text
      throwIfAborted(signal)
      return text
    })
  })

  return serializeCsvTable({ columns, sourceRows, dialect: CSV_DIALECT })
}

function normalizeSheetDimension(value: number) {
  return Number.isFinite(value) && value > 0 ? Math.floor(value) : 0
}

function sanitizeFileNamePart(value: string, fallback = "sheet") {
  const sanitized = value.trim().replace(/[\x00-\x1f\x7f/\\?%*:|"<>]+/g, "-")
  return /[^\s.-]/u.test(sanitized) ? sanitized : fallback
}

function throwIfAborted(signal: AbortSignal | undefined) {
  if (signal?.aborted) {
    throw new DOMException("Download was cancelled.", "AbortError")
  }
}

import {
  isTabDelimited,
  normalizeCsvDelimiter,
  type CsvDialect,
} from "@/lib/csv"
import type { ViewerDownloadAction } from "@/lib/viewer-download"
import type { ViewerResource } from "@/lib/viewer-resource"

export function escapeDelimitedField(value: string, delimiter: string): string {
  const text = value ?? ""
  return text.includes(delimiter) || /["\r\n]/.test(text)
    ? `"${text.replace(/"/g, '""')}"`
    : text
}

export function serializeCsvTable({
  columns,
  sourceRows,
  dialect,
}: {
  columns: string[]
  sourceRows: string[][]
  dialect: CsvDialect
}): string {
  const delimiter =
    normalizeCsvDelimiter(dialect.delimiter) ?? dialect.delimiter
  const lines = [
    columns
      .map((value) => escapeDelimitedField(value, delimiter))
      .join(delimiter),
  ]
  for (const sourceRow of sourceRows) {
    const row = fitExportRow(sourceRow, columns.length)
    lines.push(
      row.map((value) => escapeDelimitedField(value, delimiter)).join(delimiter)
    )
  }
  return lines.join("\r\n")
}

function fitExportRow(row: string[], columnCount: number): string[] {
  const out = row.slice(0, columnCount)
  while (out.length < columnCount) out.push("")
  return out
}

export function defaultCsvDownloadName(dialect: CsvDialect): string {
  return isTabDelimited(dialect) ? "data.tsv" : "data.csv"
}

export function createCsvExportAction({
  columns,
  sourceRows,
  dialect,
  fileName,
  isDisabled,
}: {
  columns: string[]
  sourceRows: string[][]
  dialect: CsvDialect
  fileName: string
  isDisabled?: boolean
}): ViewerDownloadAction {
  return {
    id: "csv-export-table",
    label: "Export table",
    fileName,
    origin: "derived",
    isDisabled,
    getPayload: () => ({
      kind: "text",
      text: serializeCsvTable({ columns, sourceRows, dialect }),
      mimeType: isTabDelimited(dialect)
        ? "text/tab-separated-values;charset=utf-8"
        : "text/csv;charset=utf-8",
    }),
  }
}

export function csvViewerDownloadActions({
  resource,
  columns,
  sourceRows,
  dialect,
  fileName,
  canExportTable,
}: {
  resource: ViewerResource | null
  columns: string[]
  sourceRows: string[][]
  dialect: CsvDialect
  fileName: string
  canExportTable: boolean
}): ViewerDownloadAction[] {
  const actions: ViewerDownloadAction[] = []
  if (resource) {
    actions.push({
      ...resource.originalDownload,
      label: "Download original",
    })
  }
  actions.push(
    createCsvExportAction({
      columns,
      sourceRows,
      dialect,
      fileName,
      isDisabled: !canExportTable,
    })
  )
  return actions
}

"use client"

import * as React from "react"

import { xlsxColumnLabel, type XlsxCell } from "@/lib/xlsx-workbook"
import { fixedGridColumnWidths } from "@/components/ui/fixed-grid-columns"
import {
  getFixedGridCanvasStyle,
  getFixedGridRowWindowStyle,
} from "@/components/ui/fixed-grid-layout"
import type { GridCellCoordinate } from "@/components/ui/fixed-grid-selection"
import { buildVirtualGridTemplate } from "@/components/ui/fixed-grid-template"
import { FixedGridViewport } from "@/components/ui/fixed-grid-viewport"
import {
  useFixedGridVirtualization,
  useFixedRowPool,
  type FixedGridRowPoolSlot,
} from "@/components/ui/fixed-grid-virtualization"
import { HeaderAwareScrollbar } from "@/components/ui/header-aware-scrollbar"
import {
  XLSX_BASE_COLUMN_WIDTH,
  XLSX_BASE_FONT_SIZE,
  XLSX_BASE_GUTTER_WIDTH,
  XLSX_BASE_ROW_HEIGHT,
} from "@/components/ui/xlsx-grid-constants"
import {
  Spacer,
  XlsxGridRow,
  type XlsxGridColumnItem,
} from "@/components/ui/xlsx-grid-row"
import { XLSX_SCROLLBAR_CSS } from "@/components/ui/xlsx-grid-scrollbar"
import { ScrollerShell } from "@/components/ui/xlsx-shadow-scope"
import {
  useXlsxRowPatcher,
  type XlsxRowPatchState,
} from "@/registry/new-york-v4/ui/xlsx-viewer-row-patcher"

export { XlsxGridSkeleton } from "@/components/ui/xlsx-grid-skeleton"

const ROW_OVERSCAN = 4
const JUMP_ROW_OVERSCAN = 0
const COLUMN_OVERSCAN = 2
const JUMP_COLUMN_OVERSCAN = 0

export interface XlsxScrollRequest {
  sheetIndex: number
  rowIndex: number
  columnIndex: number
  behavior: ScrollBehavior
  nonce: number
}

type XlsxGridCellRef = GridCellCoordinate

export function XlsxGrid({
  rowCount,
  columnCount,
  getCell,
  sheetName,
  scale,
  activeCell,
  scrollRequest,
  isolateStyles,
  viewportRef,
}: {
  rowCount: number
  columnCount: number
  sheetName: string
  getCell: (rowIndex: number, columnIndex: number) => XlsxCell
  scale: number
  activeCell?: XlsxGridCellRef | null
  scrollRequest?: XlsxScrollRequest | null
  isolateStyles: boolean
  viewportRef?: React.RefObject<HTMLDivElement | null>
}) {
  const safeRowCount = normalizeGridCount(rowCount)
  const safeColumnCount = normalizeGridCount(columnCount)
  const safeScale = normalizeGridScale(scale)
  const rowHeight = Math.round(XLSX_BASE_ROW_HEIGHT * safeScale)
  const columnWidth = Math.round(XLSX_BASE_COLUMN_WIDTH * safeScale)
  const gutterWidth = Math.round(XLSX_BASE_GUTTER_WIDTH * safeScale)
  const fontSize = XLSX_BASE_FONT_SIZE * safeScale

  const scrollRef = React.useRef<HTMLDivElement>(null)
  const rowWindowRef = React.useRef<HTMLDivElement>(null)
  const setScrollElement = React.useCallback(
    (element: HTMLDivElement | null) => {
      scrollRef.current = element
      if (viewportRef) viewportRef.current = element
    },
    [viewportRef]
  )
  const columnItemsRef = React.useRef<XlsxGridColumnItem[]>([])
  const getRowPatchState = React.useCallback(
    (): XlsxRowPatchState => ({
      activeCell: activeCell ?? null,
      columnCount: safeColumnCount,
      columnItems: columnItemsRef.current,
      getCell,
      rowCount: safeRowCount,
      rowHeight,
      sheetName,
    }),
    [activeCell, getCell, rowHeight, safeColumnCount, safeRowCount, sheetName]
  )
  const rowPatcher = useXlsxRowPatcher({
    rowWindowRef,
    getState: getRowPatchState,
  })
  const rowScrollStrategy = React.useMemo(
    () => ({ handleViewport: rowPatcher.patch }),
    [rowPatcher]
  )

  const {
    virtualRows,
    totalRowSize,
    totalColumnSize,
    columnItems: virtualColumnItems,
    leftPad,
    rightPad,
    scrollToCell,
    viewportClientHeight,
  } = useFixedGridVirtualization({
    rowCount: safeRowCount,
    columnCount: safeColumnCount,
    rowSize: rowHeight,
    columnSize: columnWidth,
    rowOverscan: ROW_OVERSCAN,
    columnOverscan: COLUMN_OVERSCAN,
    jumpRowOverscan: JUMP_ROW_OVERSCAN,
    jumpColumnOverscan: JUMP_COLUMN_OVERSCAN,
    minimumRenderedRows: 1,
    rowScrollStrategy,
    scrollRef,
  })

  const requestNonce = scrollRequest?.nonce
  React.useEffect(() => {
    if (!scrollRequest) return
    scrollToCell({
      rowIndex: scrollRequest.rowIndex,
      columnIndex: scrollRequest.columnIndex,
      behavior: scrollRequest.behavior,
      align: "center",
    })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [requestNonce])

  const columnItems = React.useMemo(
    () =>
      virtualColumnItems.map((item) => ({
        key: String(item.index),
        widthPx: item.widthPx,
        metadata: { columnIndex: item.index },
      })) satisfies XlsxGridColumnItem[],
    [virtualColumnItems]
  )

  React.useLayoutEffect(() => {
    columnItemsRef.current = columnItems
  }, [columnItems])

  const gridTemplate = React.useMemo(
    () =>
      buildVirtualGridTemplate({
        leadingWidth: gutterWidth,
        leftPad,
        columnWidths: fixedGridColumnWidths(columnItems),
        rightPad,
      }),
    [gutterWidth, leftPad, columnItems, rightPad]
  )
  const totalWidth = gutterWidth + totalColumnSize
  const minimumRowPoolSize =
    Math.ceil(viewportClientHeight / rowHeight) + ROW_OVERSCAN * 2 + 2
  const rowPoolSlots = useFixedRowPool({
    minimumPoolSize: minimumRowPoolSize,
    rowCount: safeRowCount,
    virtualRows,
  })

  React.useLayoutEffect(() => {
    rowPatcher.invalidate()
  }, [
    rowPatcher,
    virtualRows,
    columnItems,
    rowHeight,
    safeRowCount,
    safeColumnCount,
    sheetName,
    getCell,
    activeCell,
  ])

  if (safeRowCount === 0 || safeColumnCount === 0) {
    return (
      <div
        className="flex flex-1 items-center justify-center bg-card text-xs text-muted-foreground"
        role="status"
        aria-label={`${sheetName} is empty`}
      >
        Empty sheet
      </div>
    )
  }

  return (
    <div
      className="flex min-h-0 flex-1 flex-col bg-card"
      style={{ fontSize }}
      data-slot="xlsx-grid"
    >
      <ScrollerShell
        isolate={isolateStyles}
        className="relative min-h-0 flex-1"
      >
        <style>{XLSX_SCROLLBAR_CSS}</style>
        <FixedGridViewport
          scrollRef={setScrollElement}
          dataSlot="xlsx-body"
          role="grid"
          aria-label={sheetName}
          aria-rowcount={safeRowCount}
          aria-colcount={safeColumnCount}
          tabIndex={0}
        >
          <div
            style={getFixedGridCanvasStyle({
              width: totalWidth,
              contain: true,
            })}
          >
            <div
              className="sticky top-0 z-20 grid border-b"
              style={{
                gridTemplateColumns: gridTemplate,
                height: rowHeight,
                backgroundColor:
                  "color-mix(in oklab, var(--card) 92%, var(--foreground))",
              }}
              aria-hidden
            >
              <div
                className="sticky left-0 z-10 border-r bg-[color-mix(in_oklab,var(--card)_94%,var(--foreground))]"
                style={{ height: rowHeight }}
              />
              <Spacer width={leftPad} />
              {columnItems.map((item) => (
                <div
                  key={item.key}
                  className="flex items-center justify-center border-r font-medium text-muted-foreground last:border-r-0"
                >
                  {xlsxColumnLabel(item.metadata.columnIndex)}
                </div>
              ))}
              <Spacer width={rightPad} />
            </div>

            <div
              ref={rowWindowRef}
              style={getFixedGridRowWindowStyle({ height: totalRowSize })}
            >
              {rowPoolSlots.map((slot) => (
                <XlsxGridRowSlot
                  key={slot.slotIndex}
                  slot={slot}
                  rowCount={safeRowCount}
                  getCell={getCell}
                  gridTemplate={gridTemplate}
                  rowHeight={rowHeight}
                  columnItems={columnItems}
                  leftPad={leftPad}
                  rightPad={rightPad}
                  activeCell={activeCell ?? null}
                />
              ))}
            </div>
          </div>
        </FixedGridViewport>
        <HeaderAwareScrollbar scrollRef={scrollRef} headerHeight={rowHeight} />
      </ScrollerShell>
    </div>
  )
}

function XlsxGridRowSlot({
  slot,
  rowCount,
  getCell,
  gridTemplate,
  rowHeight,
  columnItems,
  leftPad,
  rightPad,
  activeCell,
}: {
  slot: FixedGridRowPoolSlot
  rowCount: number
  getCell: (rowIndex: number, columnIndex: number) => XlsxCell
  gridTemplate: string
  rowHeight: number
  columnItems: XlsxGridColumnItem[]
  leftPad: number
  rightPad: number
  activeCell: XlsxGridCellRef | null
}) {
  const fallbackRowIndex =
    rowCount > 0 ? Math.min(slot.slotIndex, rowCount - 1) : 0
  const rowIndex = slot.virtualRow?.index ?? fallbackRowIndex

  return (
    <XlsxGridRow
      rowIndex={rowIndex}
      getCell={getCell}
      gridTemplate={gridTemplate}
      rowHeight={rowHeight}
      columnItems={columnItems}
      leftPad={leftPad}
      rightPad={rightPad}
      start={slot.virtualRow?.start ?? 0}
      hidden={slot.isHidden}
      activeColumnIndex={
        slot.virtualRow && activeCell?.rowIndex === rowIndex
          ? activeCell.columnIndex
          : null
      }
    />
  )
}

function normalizeGridCount(value: number) {
  return Number.isFinite(value) && value > 0 && value <= Number.MAX_SAFE_INTEGER
    ? Math.floor(value)
    : 0
}

function normalizeGridScale(value: number) {
  if (!Number.isFinite(value) || value <= 0) return 1
  return Math.min(5, Math.max(0.25, value))
}

"use client"

import * as React from "react"

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

const MINIMUM_ROW_WINDOW = 32
const INITIAL_COLUMN_WINDOW = 8
const MAX_VIRTUAL_ITEMS = 10_000
const MAX_EAGER_COLUMN_ITEMS = 10_000

export interface FixedGridColumnItem {
  index: number
  widthPx: number
}

export interface FixedGridVirtualItem {
  index: number
  start: number
  size: number
  end: number
}

export interface FixedGridRowPoolSlot {
  slotIndex: number
  virtualRow: FixedGridVirtualItem | null
  isHidden: boolean
}

export interface FixedGridScrollTarget {
  rowIndex: number
  columnIndex: number
  align?: "start" | "center" | "end" | "auto"
  behavior?: ScrollBehavior
}

export interface FixedRowScrollTarget {
  rowIndex: number
  align?: "start" | "center" | "end" | "auto"
  behavior?: ScrollBehavior
}

export type FixedGridJumpViewportResult = "handled" | "pass"

export interface FixedGridRowScrollStrategy {
  settleAfterMs?: number
  handleViewport: (viewport: FixedGridViewport) => FixedGridJumpViewportResult
}

export function useFixedRowPool({
  minimumPoolSize = 0,
  rowCount,
  virtualRows,
}: {
  minimumPoolSize?: number
  rowCount: number
  virtualRows: FixedGridVirtualItem[]
}): FixedGridRowPoolSlot[] {
  const poolSizeRef = React.useRef(0)
  const safeRowCount = fixedItemCount(rowCount)
  const safeMinimumPoolSize = fixedItemCount(minimumPoolSize)
  const nextPoolSize = Math.min(
    safeRowCount,
    Math.max(poolSizeRef.current, virtualRows.length, safeMinimumPoolSize)
  )
  poolSizeRef.current = nextPoolSize

  return React.useMemo(
    () =>
      Array.from({ length: nextPoolSize }, (_, slotIndex) => {
        const virtualRow = virtualRows[slotIndex] ?? null
        return {
          slotIndex,
          virtualRow,
          isHidden: !virtualRow,
        }
      }),
    [nextPoolSize, virtualRows]
  )
}

export function useFixedGridVirtualization({
  rowCount,
  columnCount,
  rowSize,
  columnSize,
  rowOverscan,
  columnOverscan,
  jumpRowOverscan = rowOverscan,
  jumpColumnOverscan = columnOverscan,
  minimumRenderedRows = MINIMUM_ROW_WINDOW,
  rowScrollStrategy,
  scrollRef,
  scrollElement,
  virtualizeColumns = true,
}: {
  rowCount: number
  columnCount: number
  rowSize: number
  columnSize: number
  rowOverscan: number
  columnOverscan: number
  jumpRowOverscan?: number
  jumpColumnOverscan?: number
  minimumRenderedRows?: number
  rowScrollStrategy?: FixedGridRowScrollStrategy
  scrollRef: React.RefObject<HTMLElement | null>
  scrollElement?: HTMLElement | null
  virtualizeColumns?: boolean
}) {
  const resolvedScrollElement = useResolvedScrollElement({
    scrollRef,
    scrollElement,
  })
  const viewport = useFixedGridViewport(
    resolvedScrollElement,
    rowScrollStrategy
  )

  const totalRowSize = fixedTotalSize(rowCount, rowSize)
  const totalColumnSize = fixedTotalSize(columnCount, columnSize)
  const activeRowOverscan = viewport.isJumpingRows
    ? jumpRowOverscan
    : rowOverscan
  const activeColumnOverscan =
    viewport.isJumpingColumns || viewport.isJumpingRows
      ? jumpColumnOverscan
      : columnOverscan

  const virtualRows = React.useMemo(
    () =>
      fixedVirtualItems({
        count: rowCount,
        size: rowSize,
        scrollOffset: viewport.scrollTop,
        viewportSize: viewport.clientHeight,
        overscan: activeRowOverscan,
        minimumVisibleCount: minimumRenderedRows,
      }),
    [
      rowCount,
      rowSize,
      viewport.scrollTop,
      viewport.clientHeight,
      activeRowOverscan,
      minimumRenderedRows,
    ]
  )

  const columnWindow = React.useMemo<{
    columnItems: FixedGridColumnItem[]
    leftPad: number
    rightPad: number
  }>(() => {
    if (!virtualizeColumns) {
      const safeColumnCount = fixedItemCount(columnCount)
      const safeColumnSize = fixedItemSize(columnSize)
      if (safeColumnCount > MAX_EAGER_COLUMN_ITEMS) {
        return {
          columnItems: [],
          leftPad: 0,
          rightPad: 0,
        }
      }
      return {
        columnItems: Array.from({ length: safeColumnCount }, (_, index) => ({
          index,
          widthPx: safeColumnSize,
        })),
        leftPad: 0,
        rightPad: 0,
      }
    }

    const virtualColumns = fixedVirtualItems({
      count: columnCount,
      size: columnSize,
      scrollOffset: viewport.scrollLeft,
      viewportSize: viewport.clientWidth,
      overscan: activeColumnOverscan,
      minimumVisibleCount: INITIAL_COLUMN_WINDOW,
    })

    return {
      columnItems: virtualColumns.map((item) => ({
        index: item.index,
        widthPx: item.size,
      })),
      leftPad: virtualColumns.length ? virtualColumns[0].start : 0,
      rightPad: virtualColumns.length
        ? totalColumnSize - virtualColumns[virtualColumns.length - 1].end
        : 0,
    }
  }, [
    virtualizeColumns,
    columnCount,
    columnSize,
    viewport.scrollLeft,
    viewport.clientWidth,
    activeColumnOverscan,
    totalColumnSize,
  ])

  const scrollToCell = React.useCallback(
    ({
      rowIndex,
      columnIndex,
      align = "center",
      behavior = "smooth",
    }: FixedGridScrollTarget) => {
      const scrollElement = scrollRef.current
      if (!scrollElement) return
      scrollElement.scrollTo({
        top: fixedScrollOffset({
          index: rowIndex,
          itemSize: rowSize,
          viewportSize: scrollElement.clientHeight,
          align,
        }),
        left: fixedScrollOffset({
          index: columnIndex,
          itemSize: columnSize,
          viewportSize: scrollElement.clientWidth,
          align,
        }),
        behavior,
      })
    },
    [columnSize, rowSize, scrollRef]
  )

  return {
    virtualRows,
    totalRowSize,
    totalColumnSize,
    scrollToCell,
    isJumpingRows: viewport.isJumpingRows,
    isJumpingColumns: viewport.isJumpingColumns,
    viewportClientHeight: viewport.clientHeight,
    ...columnWindow,
  }
}

export function useFixedRowVirtualization({
  rowCount,
  rowSize,
  rowOverscan,
  jumpRowOverscan = rowOverscan,
  initialViewportHeight = 0,
  scrollRef,
}: {
  rowCount: number
  rowSize: number
  rowOverscan: number
  jumpRowOverscan?: number
  initialViewportHeight?: number
  scrollRef: React.RefObject<HTMLElement | null>
}) {
  const resolvedScrollElement = useResolvedScrollElement({ scrollRef })
  const [range, setRange] = React.useState(() =>
    initialViewportHeight > 0
      ? fixedRowRange({
          rowCount,
          rowSize,
          scrollTop: 0,
          viewportHeight: initialViewportHeight,
          rowOverscan,
        })
      : { start: 0, end: 0 }
  )
  const rangeRef = React.useRef(range)
  const rafRef = React.useRef(0)
  const totalRowSize = fixedTotalSize(rowCount, rowSize)

  const setMeasuredRange = React.useCallback((next: typeof range) => {
    const current = rangeRef.current
    if (current.start === next.start && current.end === next.end) return
    rangeRef.current = next
    setRange(next)
  }, [])

  const measure = React.useCallback(() => {
    const scrollElement = resolvedScrollElement
    const safeRowCount = fixedItemCount(rowCount)
    const safeRowSize = fixedItemSize(rowSize)
    if (!scrollElement || safeRowCount <= 0 || safeRowSize <= 0) {
      setMeasuredRange({ start: 0, end: 0 })
      return
    }

    const scrollTop =
      Number.isFinite(scrollElement.scrollTop) && scrollElement.scrollTop > 0
        ? scrollElement.scrollTop
        : 0
    const viewportHeight =
      Number.isFinite(scrollElement.clientHeight) &&
      scrollElement.clientHeight > 0
        ? scrollElement.clientHeight
        : fixedViewportMetric(initialViewportHeight)
    const firstVisibleRow = clamp(
      Math.floor(scrollTop / safeRowSize),
      0,
      safeRowCount - 1
    )
    const visibleRowCount = Math.ceil(viewportHeight / safeRowSize)
    const previous = rangeRef.current
    const isJumping =
      Math.abs(firstVisibleRow - previous.start) > visibleRowCount * 0.45
    const activeOverscan = fixedOverscan(
      isJumping ? jumpRowOverscan : rowOverscan
    )
    const uncappedStart = Math.max(0, firstVisibleRow - activeOverscan)
    const uncappedEnd = Math.min(
      safeRowCount,
      firstVisibleRow + visibleRowCount + activeOverscan
    )
    const { start, end } = capVirtualRange({
      uncappedStart,
      uncappedEnd,
      visibleStart: firstVisibleRow,
      visibleEnd: Math.min(safeRowCount, firstVisibleRow + visibleRowCount),
      maxItems: MAX_VIRTUAL_ITEMS,
    })

    if (previous.end > safeRowCount || previous.start >= safeRowCount) {
      setMeasuredRange({ start, end })
      return
    }

    const bufferRows = Math.max(1, Math.floor(activeOverscan / 2))
    const visibleStart = firstVisibleRow
    const visibleEnd = Math.min(safeRowCount, firstVisibleRow + visibleRowCount)
    const hasBeforeBuffer =
      previous.start === 0 || visibleStart >= previous.start + bufferRows
    const hasAfterBuffer =
      previous.end === safeRowCount || visibleEnd <= previous.end - bufferRows

    if (hasBeforeBuffer && hasAfterBuffer) return
    setMeasuredRange({ start, end })
  }, [
    jumpRowOverscan,
    initialViewportHeight,
    rowCount,
    rowOverscan,
    rowSize,
    resolvedScrollElement,
    setMeasuredRange,
  ])

  React.useLayoutEffect(() => {
    measure()
  }, [measure])

  React.useEffect(() => {
    const scrollElement = resolvedScrollElement
    if (!scrollElement) return

    const scheduleMeasure = () => {
      if (rafRef.current) return
      let didRun = false
      const frame = requestAnimationFrame(() => {
        didRun = true
        rafRef.current = 0
        measure()
      })
      rafRef.current = didRun ? 0 : frame
    }

    scrollElement.addEventListener("scroll", scheduleMeasure, {
      passive: true,
    })
    const observer =
      typeof ResizeObserver !== "undefined"
        ? new ResizeObserver(scheduleMeasure)
        : null
    observer?.observe(scrollElement)
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current)
      scrollElement.removeEventListener("scroll", scheduleMeasure)
      observer?.disconnect()
    }
  }, [resolvedScrollElement, measure])

  const virtualRows = React.useMemo(
    () =>
      Array.from({ length: range.end - range.start }, (_, offset) => {
        const index = range.start + offset
        const size = fixedItemSize(rowSize)
        const start = index * size
        return {
          index,
          start,
          size,
          end: start + size,
        }
      }),
    [range, rowSize]
  )

  const scrollToRow = React.useCallback(
    ({
      rowIndex,
      align = "center",
      behavior = "smooth",
    }: FixedRowScrollTarget) => {
      const scrollElement = scrollRef.current
      if (!scrollElement) return
      scrollElement.scrollTo({
        top: fixedScrollOffset({
          index: rowIndex,
          itemSize: rowSize,
          viewportSize: scrollElement.clientHeight,
          align,
        }),
        behavior,
      })
    },
    [rowSize, scrollRef]
  )

  return {
    virtualRows,
    totalRowSize,
    scrollToRow,
  }
}

function fixedRowRange({
  rowCount,
  rowSize,
  scrollTop,
  viewportHeight,
  rowOverscan,
}: {
  rowCount: number
  rowSize: number
  scrollTop: number
  viewportHeight: number
  rowOverscan: number
}) {
  const safeRowCount = fixedItemCount(rowCount)
  const safeRowSize = fixedItemSize(rowSize)
  if (safeRowCount <= 0 || safeRowSize <= 0) return { start: 0, end: 0 }

  const safeScrollTop =
    Number.isFinite(scrollTop) && scrollTop > 0 ? scrollTop : 0
  const safeViewportHeight = fixedViewportMetric(viewportHeight)
  const firstVisibleRow = clamp(
    Math.floor(safeScrollTop / safeRowSize),
    0,
    safeRowCount - 1
  )
  const visibleRowCount = Math.ceil(safeViewportHeight / safeRowSize)
  const activeOverscan = fixedOverscan(rowOverscan)
  const uncappedStart = Math.max(0, firstVisibleRow - activeOverscan)
  const uncappedEnd = Math.min(
    safeRowCount,
    firstVisibleRow + visibleRowCount + activeOverscan
  )
  return capVirtualRange({
    uncappedStart,
    uncappedEnd,
    visibleStart: firstVisibleRow,
    visibleEnd: Math.min(safeRowCount, firstVisibleRow + visibleRowCount),
    maxItems: MAX_VIRTUAL_ITEMS,
  })
}

export interface FixedGridViewport {
  scrollTop: number
  scrollLeft: number
  clientHeight: number
  clientWidth: number
  isJumpingRows: boolean
  isJumpingColumns: boolean
}

interface FixedVirtualWindow {
  count: number
  size: number
  scrollOffset: number
  viewportSize: number
  overscan: number
  minimumVisibleCount?: number
}

const emptyFixedGridViewport: FixedGridViewport = {
  scrollTop: 0,
  scrollLeft: 0,
  clientHeight: 0,
  clientWidth: 0,
  isJumpingRows: false,
  isJumpingColumns: false,
}

function useResolvedScrollElement({
  scrollRef,
  scrollElement,
}: {
  scrollRef: React.RefObject<HTMLElement | null>
  scrollElement?: HTMLElement | null
}) {
  const [resolvedScrollElement, setResolvedScrollElement] =
    React.useState<HTMLElement | null>(scrollElement ?? scrollRef.current)

  useIsomorphicLayoutEffect(() => {
    const nextScrollElement = scrollElement ?? scrollRef.current
    if (resolvedScrollElement !== nextScrollElement) {
      setResolvedScrollElement(nextScrollElement)
    }
  })

  return resolvedScrollElement
}

function useFixedGridViewport(
  scrollElement: HTMLElement | null | undefined,
  rowScrollStrategy?: FixedGridRowScrollStrategy
) {
  const [viewport, setViewport] = React.useState<FixedGridViewport>(
    emptyFixedGridViewport
  )

  useIsomorphicLayoutEffect(() => {
    if (!scrollElement) {
      setViewport((current) =>
        fixedGridViewportEqual(current, emptyFixedGridViewport)
          ? current
          : emptyFixedGridViewport
      )
      return
    }

    let frame = 0
    let settleTimeout = 0
    let lastScrollTop = scrollElement.scrollTop
    let lastScrollLeft = scrollElement.scrollLeft

    const commitViewport = (next: FixedGridViewport) => {
      setViewport((current) => {
        return fixedGridViewportEqual(current, next) ? current : next
      })
    }

    const readViewport = () => {
      frame = 0
      const scrollTop = fixedViewportMetric(scrollElement.scrollTop)
      const scrollLeft = fixedViewportMetric(scrollElement.scrollLeft)
      const clientHeight = fixedViewportMetric(scrollElement.clientHeight)
      const clientWidth = fixedViewportMetric(scrollElement.clientWidth)
      const rowDelta = Math.abs(scrollTop - lastScrollTop)
      const columnDelta = Math.abs(scrollLeft - lastScrollLeft)
      lastScrollTop = scrollTop
      lastScrollLeft = scrollLeft

      const next: FixedGridViewport = {
        scrollTop,
        scrollLeft,
        clientHeight,
        clientWidth,
        isJumpingRows: rowDelta > clientHeight * 0.45,
        isJumpingColumns: columnDelta > clientWidth * 0.45,
      }

      if (
        rowDelta > 0 &&
        rowScrollStrategy?.handleViewport(next) === "handled"
      ) {
        if (settleTimeout) window.clearTimeout(settleTimeout)
        settleTimeout = window.setTimeout(() => {
          settleTimeout = 0
          commitViewport(next)
        }, rowScrollStrategy.settleAfterMs ?? 80)
        return
      }

      if (settleTimeout) {
        window.clearTimeout(settleTimeout)
        settleTimeout = 0
      }
      commitViewport(next)
    }

    const scheduleRead = () => {
      if (frame) return
      let didRun = false
      const nextFrame = requestAnimationFrame(() => {
        didRun = true
        readViewport()
      })
      frame = didRun ? 0 : nextFrame
    }

    readViewport()
    scrollElement.addEventListener("scroll", scheduleRead, { passive: true })
    const observer =
      typeof ResizeObserver !== "undefined"
        ? new ResizeObserver(scheduleRead)
        : null
    observer?.observe(scrollElement)

    return () => {
      if (frame) cancelAnimationFrame(frame)
      if (settleTimeout) window.clearTimeout(settleTimeout)
      scrollElement.removeEventListener("scroll", scheduleRead)
      observer?.disconnect()
    }
  }, [scrollElement, rowScrollStrategy])

  return viewport
}

export function fixedVirtualItems({
  count,
  size,
  scrollOffset,
  viewportSize,
  overscan,
  minimumVisibleCount = 1,
}: FixedVirtualWindow): FixedGridVirtualItem[] {
  if (!Number.isFinite(count) || !Number.isFinite(size)) return []
  const itemCount = Math.floor(count)
  if (itemCount <= 0 || size <= 0) return []
  const safeScrollOffset =
    Number.isFinite(scrollOffset) && scrollOffset > 0 ? scrollOffset : 0
  const safeViewportSize = Number.isFinite(viewportSize) ? viewportSize : 0
  const safeOverscan =
    Number.isFinite(overscan) && overscan > 0 ? Math.floor(overscan) : 0
  const safeMinimumVisibleCount =
    Number.isFinite(minimumVisibleCount) && minimumVisibleCount > 0
      ? Math.ceil(minimumVisibleCount)
      : 1
  const effectiveViewportSize = Math.max(
    safeViewportSize,
    size * safeMinimumVisibleCount
  )
  const visibleStart = clamp(
    Math.floor(safeScrollOffset / size),
    0,
    itemCount - 1
  )
  const visibleEnd = clamp(
    Math.ceil((safeScrollOffset + effectiveViewportSize) / size),
    visibleStart,
    itemCount - 1
  )
  const uncappedStart = Math.max(0, visibleStart - safeOverscan)
  const uncappedEndInclusive = Math.min(
    itemCount - 1,
    visibleEnd + safeOverscan
  )
  const { start, end } = capVirtualRange({
    uncappedStart,
    uncappedEnd: uncappedEndInclusive + 1,
    visibleStart,
    visibleEnd: visibleEnd + 1,
    maxItems: MAX_VIRTUAL_ITEMS,
  })
  return Array.from({ length: end - start }, (_, offset) => {
    const index = start + offset
    const itemStart = index * size
    return {
      index,
      start: itemStart,
      size,
      end: itemStart + size,
    }
  })
}

function capVirtualRange({
  uncappedStart,
  uncappedEnd,
  visibleStart,
  visibleEnd,
  maxItems,
}: {
  uncappedStart: number
  uncappedEnd: number
  visibleStart: number
  visibleEnd: number
  maxItems: number
}) {
  const length = uncappedEnd - uncappedStart
  if (length <= maxItems) return { start: uncappedStart, end: uncappedEnd }

  const visibleLength = Math.max(0, visibleEnd - visibleStart)
  if (visibleLength >= maxItems) {
    return {
      start: visibleStart,
      end: visibleStart + maxItems,
    }
  }

  const remaining = maxItems - visibleLength
  const before = Math.min(
    visibleStart - uncappedStart,
    Math.floor(remaining / 2)
  )
  let start = visibleStart - before
  let end = start + maxItems

  if (end > uncappedEnd) {
    end = uncappedEnd
    start = Math.max(uncappedStart, end - maxItems)
  }

  return { start, end }
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

function fixedTotalSize(count: number, size: number) {
  if (
    !Number.isFinite(count) ||
    !Number.isFinite(size) ||
    count <= 0 ||
    size <= 0
  ) {
    return 0
  }
  const totalSize = Math.floor(count) * size
  return Number.isFinite(totalSize) ? totalSize : 0
}

function fixedItemCount(count: number) {
  return Number.isFinite(count) && count > 0 ? Math.floor(count) : 0
}

function fixedItemSize(size: number) {
  return Number.isFinite(size) && size > 0 ? size : 0
}

function fixedOverscan(overscan: number) {
  return Number.isFinite(overscan) && overscan > 0 ? Math.floor(overscan) : 0
}

function fixedViewportMetric(value: number) {
  return Number.isFinite(value) && value > 0 ? value : 0
}

export function fixedScrollOffset({
  index,
  itemSize,
  viewportSize,
  align,
}: {
  index: number
  itemSize: number
  viewportSize: number
  align: NonNullable<FixedGridScrollTarget["align"]>
}) {
  if (
    !Number.isSafeInteger(index) ||
    !Number.isFinite(itemSize) ||
    !Number.isFinite(viewportSize) ||
    index < 0 ||
    itemSize <= 0 ||
    viewportSize < 0
  ) {
    return 0
  }
  const start = index * itemSize
  if (align === "end") return Math.max(0, start - viewportSize + itemSize)
  if (align === "center") {
    return Math.max(0, start - viewportSize / 2 + itemSize / 2)
  }
  return Math.max(0, start)
}

function fixedGridViewportEqual(
  left: FixedGridViewport,
  right: FixedGridViewport
) {
  return (
    left.scrollTop === right.scrollTop &&
    left.scrollLeft === right.scrollLeft &&
    left.clientHeight === right.clientHeight &&
    left.clientWidth === right.clientWidth &&
    left.isJumpingRows === right.isJumpingRows &&
    left.isJumpingColumns === right.isJumpingColumns
  )
}

export function buildVirtualGridTemplate({
  leadingWidth,
  leftPad,
  columnWidths,
  rightPad,
}: {
  leadingWidth: number
  leftPad: number
  columnWidths: readonly number[]
  rightPad: number
}) {
  const columns = columnWidths.map(formatTemplateWidth).join(" ")
  return [
    formatTemplateWidth(leadingWidth),
    formatTemplateWidth(leftPad),
    columns,
    formatTemplateWidth(rightPad),
  ]
    .filter(Boolean)
    .join(" ")
}

function formatTemplateWidth(width: number) {
  return `${Number.isFinite(width) && width > 0 ? width : 0}px`
}

export interface FixedGridColumn<Metadata = unknown> {
  key: string
  widthPx: number
  metadata?: Metadata
}

export function buildFixedGridColumns<Item, Metadata = unknown>({
  items,
  getKey,
  getWidthPx,
  getMetadata,
}: {
  items: readonly Item[]
  getKey: (item: Item, index: number) => string
  getWidthPx: (item: Item, index: number) => number
  getMetadata?: (item: Item, index: number) => Metadata | undefined
}): FixedGridColumn<Metadata>[] {
  return items.map((item, index) => {
    const metadata = getMetadata?.(item, index)
    const widthPx = normalizeFixedGridColumnWidth(getWidthPx(item, index))
    return metadata === undefined
      ? {
          key: getKey(item, index),
          widthPx,
        }
      : {
          key: getKey(item, index),
          widthPx,
          metadata,
        }
  })
}

export function fixedGridColumnWidths(
  columns: readonly Pick<FixedGridColumn, "widthPx">[]
) {
  return columns.map((column) => normalizeFixedGridColumnWidth(column.widthPx))
}

function normalizeFixedGridColumnWidth(widthPx: number) {
  return Number.isFinite(widthPx) && widthPx > 0 ? widthPx : 0
}

import type * as React from "react"

type CssLength = number | string

export function getFixedGridCanvasStyle({
  width,
  minWidth = "100%",
  contain = false,
}: {
  width?: CssLength
  minWidth?: CssLength
  contain?: boolean
}): React.CSSProperties {
  return {
    position: "relative",
    ...cssLengthProperty("width", width),
    ...cssLengthProperty("minWidth", minWidth),
    ...(contain ? { contain: "layout paint style" } : null),
  }
}

export function getFixedGridRowWindowStyle({
  height,
  minWidth,
}: {
  height: CssLength
  minWidth?: CssLength
}): React.CSSProperties {
  return {
    position: "relative",
    ...cssLengthProperty("height", height),
    ...cssLengthProperty("minWidth", minWidth),
  }
}

function formatCssLength(value: CssLength | undefined) {
  if (typeof value === "string") return value.trim() ? value : undefined
  if (typeof value !== "number") return value
  return Number.isFinite(value) && value >= 0 ? `${value}px` : undefined
}

function cssLengthProperty<Property extends "height" | "minWidth" | "width">(
  property: Property,
  value: CssLength | undefined
): Pick<React.CSSProperties, Property> | object {
  const formattedValue = formatCssLength(value)
  return formattedValue === undefined ? {} : { [property]: formattedValue }
}

export interface GridCellCoordinate {
  rowIndex: number
  columnIndex: number
}

export function isSameGridCell(
  left: GridCellCoordinate | null | undefined,
  right: GridCellCoordinate | null | undefined
) {
  return (
    isValidGridCellCoordinate(left) &&
    isValidGridCellCoordinate(right) &&
    left.rowIndex === right.rowIndex &&
    left.columnIndex === right.columnIndex
  )
}

export function gridCellKey({ rowIndex, columnIndex }: GridCellCoordinate) {
  if (!isValidGridCellCoordinate({ rowIndex, columnIndex })) return null
  return `${rowIndex}:${columnIndex}`
}

export function parseGridCellKey(key: string): GridCellCoordinate | null {
  const [rowIndexText, columnIndexText, extra] = key.split(":")
  if (extra !== undefined) return null
  if (!rowIndexText || !columnIndexText) return null
  if (!isUnsignedIntegerText(rowIndexText) || !isUnsignedIntegerText(columnIndexText)) {
    return null
  }

  const rowIndex = Number(rowIndexText)
  const columnIndex = Number(columnIndexText)
  if (!isValidGridCellCoordinate({ rowIndex, columnIndex })) {
    return null
  }

  return { rowIndex, columnIndex }
}

function isUnsignedIntegerText(value: string) {
  return /^(0|[1-9]\d*)$/.test(value)
}

function isValidGridCellCoordinate(
  coordinate: GridCellCoordinate | null | undefined
): coordinate is GridCellCoordinate {
  return (
    !!coordinate &&
    Number.isSafeInteger(coordinate.rowIndex) &&
    Number.isSafeInteger(coordinate.columnIndex) &&
    coordinate.rowIndex >= 0 &&
    coordinate.columnIndex >= 0
  )
}

