"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import type { XlsxSheetMeta } from "@/lib/xlsx-workbook"

export const XLSX_SHEET_TABS_HEIGHT_PX = 36
const TAB_HEIGHT_PX = 28
const SCROLL_EPSILON_PX = 1
const TAB_MIN_WIDTH_PX = 92
const TAB_MAX_WIDTH_PX = 184
const TAB_GAP_PX = 2
const TAB_SCROLL_INLINE_PADDING_PX = 12
const PREFERRED_VISIBLE_TABS = 6
const LARGE_REVEAL_DISTANCE_MULTIPLIER = 1.25
const OVERFLOW_REVEAL_DESKTOP_PX = 22
const OVERFLOW_REVEAL_MOBILE_PX = 16
const OVERFLOW_REVEAL_MIN_PX = 8

interface SheetTabScrollState {
  canScrollLeft: boolean
  canScrollRight: boolean
  isOverflowing: boolean
  viewportWidth: number
}

interface TabRevealGeometry {
  activeIndex: number
  activeLeft: number
  activeWidth: number
  scrollLeft: number
  scrollWidth: number
  sheetCount: number
  viewportWidth: number
}

function scrollTabsTo(
  scrollElement: HTMLDivElement,
  left: number,
  behavior: ScrollBehavior
) {
  const maxScrollLeft = Math.max(
    0,
    scrollElement.scrollWidth - scrollElement.clientWidth
  )
  const clampedLeft = Math.min(maxScrollLeft, Math.max(0, left))

  if (typeof scrollElement.scrollTo === "function") {
    scrollElement.scrollTo({ left: clampedLeft, behavior })
  } else {
    scrollElement.scrollLeft = clampedLeft
  }
}

function resolveOverflowRevealPx(viewportWidth: number, tabWidth: number) {
  const targetReveal = resolveOverflowRevealTargetPx(viewportWidth)
  const maxTabReveal = Math.max(
    OVERFLOW_REVEAL_MIN_PX,
    Math.floor(tabWidth * 0.35)
  )

  return Math.max(OVERFLOW_REVEAL_MIN_PX, Math.min(targetReveal, maxTabReveal))
}

function resolveOverflowRevealTargetPx(viewportWidth: number) {
  return viewportWidth <= 420
    ? OVERFLOW_REVEAL_MOBILE_PX
    : OVERFLOW_REVEAL_DESKTOP_PX
}

function resolveTabRevealScrollLeft({
  activeIndex,
  activeLeft,
  activeWidth,
  scrollLeft,
  scrollWidth,
  sheetCount,
  viewportWidth,
}: TabRevealGeometry) {
  const maxScrollLeft = Math.max(0, scrollWidth - viewportWidth)
  if (maxScrollLeft <= SCROLL_EPSILON_PX) return 0

  if (activeIndex <= 0) return 0
  if (activeIndex >= sheetCount - 1) return maxScrollLeft

  const activeRight = activeLeft + activeWidth
  const overflowRevealPx = resolveOverflowRevealPx(viewportWidth, activeWidth)
  const visibleLeft = scrollLeft + overflowRevealPx
  const visibleRight = scrollLeft + viewportWidth - overflowRevealPx

  let nextScrollLeft = scrollLeft

  if (activeLeft < visibleLeft) {
    nextScrollLeft = activeLeft - overflowRevealPx
  } else if (activeRight > visibleRight) {
    nextScrollLeft = activeRight - viewportWidth + overflowRevealPx
  }

  return Math.min(maxScrollLeft, Math.max(0, nextScrollLeft))
}

function readScrollState(scrollElement: HTMLElement): SheetTabScrollState {
  const maxScrollLeft = Math.max(
    0,
    scrollElement.scrollWidth - scrollElement.clientWidth
  )

  return {
    canScrollLeft: scrollElement.scrollLeft > SCROLL_EPSILON_PX,
    canScrollRight:
      scrollElement.scrollLeft < maxScrollLeft - SCROLL_EPSILON_PX,
    isOverflowing: maxScrollLeft > SCROLL_EPSILON_PX,
    viewportWidth: scrollElement.clientWidth,
  }
}

function resolveTabWidth(viewportWidth: number, sheetCount: number) {
  if (viewportWidth <= 0 || sheetCount <= 0) return undefined

  const preferredVisibleTabs = Math.min(sheetCount, PREFERRED_VISIBLE_TABS)
  const isOverflowing = sheetCount > preferredVisibleTabs
  const overflowRevealPx = isOverflowing
    ? resolveOverflowRevealTargetPx(viewportWidth)
    : 0
  const visibleTabs = isOverflowing
    ? Math.max(
        1,
        Math.min(
          preferredVisibleTabs,
          Math.floor(
            (viewportWidth -
              TAB_SCROLL_INLINE_PADDING_PX -
              overflowRevealPx +
              TAB_GAP_PX) /
              (TAB_MIN_WIDTH_PX + TAB_GAP_PX)
          )
        )
      )
    : preferredVisibleTabs
  const gapCount = isOverflowing ? visibleTabs : Math.max(0, sheetCount - 1)
  const availableWidth = Math.max(
    0,
    viewportWidth -
      TAB_SCROLL_INLINE_PADDING_PX -
      gapCount * TAB_GAP_PX -
      overflowRevealPx
  )

  return Math.round(
    Math.min(
      TAB_MAX_WIDTH_PX,
      Math.max(TAB_MIN_WIDTH_PX, availableWidth / visibleTabs)
    )
  )
}

export function XlsxSheetTabs({
  sheets,
  activeSheetIndex,
  onSelectSheet,
}: {
  sheets: XlsxSheetMeta[]
  activeSheetIndex: number
  onSelectSheet: (sheetIndex: number) => void
}) {
  const scrollRef = React.useRef<HTMLDivElement>(null)
  const listRef = React.useRef<HTMLDivElement>(null)
  const tabRefs = React.useRef<(HTMLButtonElement | null)[]>([])
  const [scrollState, setScrollState] = React.useState<SheetTabScrollState>({
    canScrollLeft: false,
    canScrollRight: false,
    isOverflowing: false,
    viewportWidth: 0,
  })
  const tabWidth = resolveTabWidth(scrollState.viewportWidth, sheets.length)

  const updateScrollState = React.useCallback(() => {
    const scrollElement = scrollRef.current
    if (!scrollElement) return

    const nextScrollState = readScrollState(scrollElement)

    setScrollState((current) =>
      current.canScrollLeft === nextScrollState.canScrollLeft &&
      current.canScrollRight === nextScrollState.canScrollRight &&
      current.isOverflowing === nextScrollState.isOverflowing &&
      current.viewportWidth === nextScrollState.viewportWidth
        ? current
        : nextScrollState
    )
  }, [])

  const scrollTabsBy = React.useCallback(
    (delta: number) => {
      const scrollElement = scrollRef.current
      if (!scrollElement) return false

      const maxScrollLeft = Math.max(
        0,
        scrollElement.scrollWidth - scrollElement.clientWidth
      )
      const nextScrollLeft = scrollElement.scrollLeft + delta
      const clampedScrollLeft = Math.min(
        maxScrollLeft,
        Math.max(0, nextScrollLeft)
      )

      if (Math.abs(clampedScrollLeft - scrollElement.scrollLeft) <= 0.5) {
        return false
      }

      scrollElement.scrollLeft = clampedScrollLeft
      updateScrollState()
      return true
    },
    [updateScrollState]
  )

  const onTabsWheel = React.useCallback(
    (event: WheelEvent) => {
      const scrollElement = scrollRef.current
      if (!scrollElement || !readScrollState(scrollElement).isOverflowing) {
        return
      }

      const dominantDelta =
        Math.abs(event.deltaX) > Math.abs(event.deltaY)
          ? event.deltaX
          : event.deltaY
      if (dominantDelta === 0) return

      if (!scrollTabsBy(dominantDelta)) return
      event.preventDefault()
    },
    [scrollTabsBy]
  )

  React.useLayoutEffect(() => {
    updateScrollState()

    const scrollElement = scrollRef.current
    const listElement = listRef.current
    if (!scrollElement) return

    const ResizeObserverCtor = globalThis.ResizeObserver
    const resizeObserver =
      typeof ResizeObserverCtor === "function"
        ? new ResizeObserverCtor(updateScrollState)
        : null
    resizeObserver?.observe(scrollElement)
    if (listElement) resizeObserver?.observe(listElement)

    scrollElement.addEventListener("scroll", updateScrollState, {
      passive: true,
    })
    scrollElement.addEventListener("wheel", onTabsWheel, { passive: false })
    return () => {
      resizeObserver?.disconnect()
      scrollElement.removeEventListener("scroll", updateScrollState)
      scrollElement.removeEventListener("wheel", onTabsWheel)
    }
  }, [onTabsWheel, sheets.length, updateScrollState])

  React.useLayoutEffect(() => {
    const scrollElement = scrollRef.current
    const activeTab = tabRefs.current[activeSheetIndex]
    if (!scrollElement || !activeTab) return

    const nextLeft = resolveTabRevealScrollLeft({
      activeIndex: activeSheetIndex,
      activeLeft: activeTab.offsetLeft,
      activeWidth: activeTab.offsetWidth,
      scrollLeft: scrollElement.scrollLeft,
      scrollWidth: scrollElement.scrollWidth,
      sheetCount: sheets.length,
      viewportWidth: scrollElement.clientWidth,
    })

    if (Math.abs(nextLeft - scrollElement.scrollLeft) > SCROLL_EPSILON_PX) {
      const distance = Math.abs(nextLeft - scrollElement.scrollLeft)
      scrollTabsTo(
        scrollElement,
        nextLeft,
        distance > scrollElement.clientWidth * LARGE_REVEAL_DISTANCE_MULTIPLIER
          ? "auto"
          : "smooth"
      )
    }

    window.requestAnimationFrame(updateScrollState)
  }, [activeSheetIndex, sheets.length, tabWidth, updateScrollState])

  if (sheets.length <= 1) return null

  const selectSheet = (sheetIndex: number) => {
    if (sheetIndex !== activeSheetIndex) onSelectSheet(sheetIndex)
  }

  const onTabKeyDown = (
    event: React.KeyboardEvent<HTMLButtonElement>,
    sheetIndex: number
  ) => {
    const lastSheetIndex = sheets.length - 1
    let nextSheetIndex: number | null = null

    if (event.key === "ArrowLeft") {
      nextSheetIndex = sheetIndex > 0 ? sheetIndex - 1 : lastSheetIndex
    } else if (event.key === "ArrowRight") {
      nextSheetIndex = sheetIndex < lastSheetIndex ? sheetIndex + 1 : 0
    } else if (event.key === "Home") {
      nextSheetIndex = 0
    } else if (event.key === "End") {
      nextSheetIndex = lastSheetIndex
    }

    if (nextSheetIndex == null) return
    event.preventDefault()
    selectSheet(nextSheetIndex)
    tabRefs.current[nextSheetIndex]?.focus()
  }

  return (
    <div
      data-slot="xlsx-viewer-tabs"
      role="tablist"
      aria-label="Workbook sheets"
      data-can-scroll-left={scrollState.canScrollLeft}
      data-can-scroll-right={scrollState.canScrollRight}
      data-overflowing={scrollState.isOverflowing}
      style={{ height: XLSX_SHEET_TABS_HEIGHT_PX }}
      className="relative flex-shrink-0 overflow-hidden border-t bg-card"
    >
      <div
        ref={scrollRef}
        data-slot="xlsx-viewer-tabs-scroll"
        className="h-full overflow-x-auto overflow-y-hidden overscroll-x-contain px-1.5 py-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
      >
        <div
          ref={listRef}
          data-slot="xlsx-viewer-tabs-track"
          className="flex min-w-max items-stretch gap-0.5"
        >
          {sheets.map((sheet, sheetIndex) => (
            <button
              key={`${sheetIndex}:${sheet.name}`}
              ref={(element) => {
                tabRefs.current[sheetIndex] = element
              }}
              type="button"
              role="tab"
              aria-selected={sheetIndex === activeSheetIndex}
              tabIndex={sheetIndex === activeSheetIndex ? 0 : -1}
              onClick={() => selectSheet(sheetIndex)}
              onKeyDown={(event) => onTabKeyDown(event, sheetIndex)}
              style={{
                height: TAB_HEIGHT_PX,
                ...(tabWidth ? { width: tabWidth } : null),
              }}
              title={sheet.name}
              data-active={sheetIndex === activeSheetIndex}
              className={cn(
                "relative flex flex-shrink-0 items-center justify-center overflow-hidden rounded-md border border-transparent px-2.5 text-xs leading-none font-medium whitespace-nowrap transition-[background-color,border-color,color,box-shadow] outline-none select-none",
                "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:ring-offset-card",
                sheetIndex === activeSheetIndex
                  ? "border-border/70 bg-background text-foreground shadow-xs"
                  : "text-muted-foreground hover:bg-muted/60 hover:text-foreground"
              )}
            >
              <span className="truncate">{sheet.name}</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  )
}

"use client"

import * as React from "react"
import { createPortal } from "react-dom"

// useLayoutEffect on the server logs a warning; fall back to useEffect there. The
// shadow root only exists on the client, so the effect is a no-op during SSR.
const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

// Drop every `:has()` style rule from a constructed sheet (recursing into
// @media/@supports/@layer blocks). The grid's own markup uses no `has-*`
// variants, so these rules never style it, but Blink would still re-run their
// invalidation against the grid subtree on each per-scroll mutation.
function stripHasRules(owner: CSSStyleSheet | CSSGroupingRule) {
  const rules = owner.cssRules
  if (!rules) return
  for (let index = rules.length - 1; index >= 0; index--) {
    const rule = rules[index]
    if ((rule as CSSStyleRule).selectorText?.includes(":has(")) {
      try {
        owner.deleteRule(index)
      } catch {
        // ignore a rule that cannot be removed
      }
    } else if ((rule as CSSGroupingRule).cssRules?.length) {
      stripHasRules(rule as CSSGroupingRule)
    }
  }
}

let sharedSheets: CSSStyleSheet[] | null = null

function getSharedSheets(): CSSStyleSheet[] {
  if (sharedSheets) return sharedSheets
  const nextSheets: CSSStyleSheet[] = []
  for (const stylesheet of Array.from(document.styleSheets)) {
    let rules: CSSRuleList
    try {
      rules = stylesheet.cssRules
    } catch {
      continue
    }
    let text = ""
    for (const rule of Array.from(rules)) text += rule.cssText + "\n"
    try {
      const sheet = new CSSStyleSheet()
      sheet.replaceSync(text)
      stripHasRules(sheet)
      nextSheets.push(sheet)
    } catch {
      // skip any sheet that cannot be reconstructed
    }
  }
  sharedSheets = nextSheets
  return nextSheets
}

function ShadowScope({
  className,
  style,
  children,
}: {
  className?: string
  style?: React.CSSProperties
  children: React.ReactNode
}) {
  const hostRef = React.useRef<HTMLDivElement>(null)
  const [root, setRoot] = React.useState<ShadowRoot | null>(null)

  useIsomorphicLayoutEffect(() => {
    const host = hostRef.current
    if (!host) return
    const shadowRoot = host.shadowRoot ?? host.attachShadow({ mode: "open" })
    try {
      shadowRoot.adoptedStyleSheets = getSharedSheets()
    } catch {
      for (const node of Array.from(
        document.querySelectorAll('style, link[rel="stylesheet"]')
      )) {
        try {
          shadowRoot.appendChild(node.cloneNode(true))
        } catch {
          // ignore a node that cannot be cloned
        }
      }
    }
    setRoot(shadowRoot)
  }, [])

  return (
    <div ref={hostRef} className={className} style={style}>
      {root ? createPortal(children, root) : null}
    </div>
  )
}

export function ScrollerShell({
  isolate,
  className,
  style,
  children,
}: {
  isolate: boolean
  className?: string
  style?: React.CSSProperties
  children: React.ReactNode
}) {
  if (isolate) {
    return (
      <ShadowScope className={className} style={style}>
        {children}
      </ShadowScope>
    )
  }
  return (
    <div className={className} style={style}>
      {children}
    </div>
  )
}

import * as React from "react"

import { resolveXlsxSheetChange, type XlsxSheetMeta } from "@/lib/xlsx-workbook"

export interface PublicXlsxCellRef {
  sheet: number
  row: number
  col: number
}

export interface InternalXlsxCellRef {
  sheetIndex: number
  rowIndex: number
  columnIndex: number
}

export type PendingXlsxScrollTarget = InternalXlsxCellRef & {
  behavior: ScrollBehavior
}

export type XlsxScrollRequest = PendingXlsxScrollTarget & {
  nonce: number
}

export interface ResolvedXlsxScrollTarget {
  sheetIndex: number
  request: PendingXlsxScrollTarget
  changed: boolean
}

export function toInternalCellRef(
  cellRef: PublicXlsxCellRef | null | undefined
): InternalXlsxCellRef | null {
  if (!isValidPublicCellRef(cellRef)) return null
  return {
    sheetIndex: cellRef.sheet,
    rowIndex: cellRef.row,
    columnIndex: cellRef.col,
  }
}

export function isValidPublicCellRef(
  cellRef: PublicXlsxCellRef | null | undefined
): cellRef is PublicXlsxCellRef {
  return (
    cellRef != null &&
    Number.isSafeInteger(cellRef.sheet) &&
    Number.isSafeInteger(cellRef.row) &&
    Number.isSafeInteger(cellRef.col) &&
    cellRef.sheet >= 0 &&
    cellRef.row >= 0 &&
    cellRef.col >= 0
  )
}

export function isValidLoadedScrollTarget(
  target: InternalXlsxCellRef,
  sheets: XlsxSheetMeta[]
): boolean {
  const sheet = sheets[target.sheetIndex]
  const rowCount = normalizeSheetDimension(sheet?.rowCount)
  const columnCount = normalizeSheetDimension(sheet?.columnCount)
  return (
    !!sheet &&
    Number.isSafeInteger(target.rowIndex) &&
    Number.isSafeInteger(target.columnIndex) &&
    target.rowIndex >= 0 &&
    target.columnIndex >= 0 &&
    target.rowIndex < rowCount &&
    target.columnIndex < columnCount
  )
}

export function resolveLoadedScrollTarget({
  activeSheetIndex,
  target,
  sheets,
}: {
  activeSheetIndex: number
  target: PendingXlsxScrollTarget
  sheets: XlsxSheetMeta[]
}): ResolvedXlsxScrollTarget | null {
  if (!isValidLoadedScrollTarget(target, sheets)) return null

  const change = resolveXlsxSheetChange({
    activeSheet: activeSheetIndex,
    requestedSheet: target.sheetIndex,
    sheetCount: sheets.length,
  })
  if (!change.accepted) return null

  return {
    sheetIndex: change.sheetIndex,
    request: target,
    changed: change.changed,
  }
}

export function useXlsxScrollController({
  activeSheetIndex,
  sheets,
  activateSheet,
}: {
  activeSheetIndex: number
  sheets: XlsxSheetMeta[] | null
  activateSheet: (sheetIndex: number) => void
}) {
  const [scrollRequest, setScrollRequest] =
    React.useState<XlsxScrollRequest | null>(null)
  const [pendingScrollTarget, setPendingScrollTarget] =
    React.useState<PendingXlsxScrollTarget | null>(null)
  const scrollNonce = React.useRef(0)

  const issueLoadedScrollTarget = React.useCallback(
    (target: PendingXlsxScrollTarget) => {
      if (!sheets) return false

      const resolved = resolveLoadedScrollTarget({
        activeSheetIndex,
        target,
        sheets,
      })
      if (!resolved) return false

      if (resolved.changed) {
        activateSheet(resolved.sheetIndex)
      }

      scrollNonce.current += 1
      setScrollRequest({
        ...resolved.request,
        nonce: scrollNonce.current,
      })
      return true
    },
    [activateSheet, activeSheetIndex, sheets]
  )

  React.useEffect(() => {
    if (!pendingScrollTarget || !sheets) return
    setPendingScrollTarget(null)
    issueLoadedScrollTarget(pendingScrollTarget)
  }, [issueLoadedScrollTarget, pendingScrollTarget, sheets])

  const scrollToCell = React.useCallback(
    (
      sheet: number,
      row: number,
      col: number,
      options?: { behavior?: ScrollBehavior }
    ) => {
      const target = toInternalCellRef({ sheet, row, col })
      if (!target) return

      const pendingTarget = {
        ...target,
        behavior: options?.behavior ?? "smooth",
      }
      if (!sheets) {
        setPendingScrollTarget(pendingTarget)
        return
      }

      issueLoadedScrollTarget(pendingTarget)
    },
    [issueLoadedScrollTarget, sheets]
  )

  return {
    scrollRequest,
    scrollToCell,
  }
}

function normalizeSheetDimension(value: number | undefined) {
  return value != null && Number.isFinite(value) && value > 0
    ? Math.floor(value)
    : 0
}

// Web Worker that owns the SheetJS parse so it never blocks the UI thread.
// @e965/xlsx is a patched, zero-dependency republish of SheetJS. The main thread
// transfers the file bytes in; the worker parses the workbook and flattens it
// into sparse compact sheets before transferring typed-array buffers back.
import * as XLSX from "@e965/xlsx"

import {
  compactWorkbookTransferBuffers,
  flattenSheetJsWorkbook,
} from "@/lib/xlsx-sheetjs-flattener"
import {
  isSpreadsheetContainer,
  XlsxWorkerError,
  type XlsxWorkerRequest,
  type XlsxWorkerResponse,
} from "@/lib/xlsx-worker-protocol"

// Cast the worker global to `Worker` so `onmessage`/`postMessage` type-check
// under the DOM lib without pulling in the conflicting "webworker" lib.
const ctx = self as unknown as Worker

ctx.onmessage = (event: MessageEvent<XlsxWorkerRequest>) => {
  try {
    if (event.data.type !== "parse_workbook") {
      throw new XlsxWorkerError(
        "parse_failed",
        "Unsupported spreadsheet request"
      )
    }

    // SheetJS sniffs arbitrary bytes into a stub sheet rather than failing, so
    // reject anything that is not a real spreadsheet container up front.
    if (!isSpreadsheetContainer(event.data.buffer)) {
      throw new XlsxWorkerError(
        "parse_failed",
        "File is not a recognized spreadsheet (.xlsx or .xls)."
      )
    }

    // cellDates formats dates as text in `.w`; we never need styles or formulae.
    const workbook = XLSX.read(event.data.buffer, {
      type: "array",
      cellDates: true,
    })
    const sheets = flattenSheetJsWorkbook(workbook)
    const response: XlsxWorkerResponse = { type: "workbook", sheets }
    ctx.postMessage(response, compactWorkbookTransferBuffers(sheets))
  } catch (error) {
    const response: XlsxWorkerResponse = {
      type: "error",
      code: error instanceof XlsxWorkerError ? error.code : "parse_failed",
      message:
        error instanceof Error ? error.message : "Failed to parse spreadsheet",
    }
    ctx.postMessage(response)
  }
}

"use client"

import * as React from "react"

export function useIsClient(): boolean {
  return React.useSyncExternalStore(
    () => () => {},
    () => true,
    () => false
  )
}

import * as React from "react"

import {
  resolveXlsxSheetChange,
  type XlsxSheetMeta,
  type XlsxSource,
} from "@/lib/xlsx-workbook"

export function useXlsxSheetState({
  defaultSheetIndex,
  onSheetChange,
}: {
  defaultSheetIndex: number
  onSheetChange?: (index: number) => void
}) {
  const [activeSheetIndex, setActiveSheetIndex] = React.useState(
    normalizeInitialSheetIndex(defaultSheetIndex)
  )
  const [sheets, setSheets] = React.useState<XlsxSheetMeta[] | null>(null)

  const reportSource = React.useCallback((source: XlsxSource) => {
    setSheets(source.sheets)
    setActiveSheetIndex((sheetIndex) =>
      clampSheetIndex(sheetIndex, source.sheets.length)
    )
  }, [])

  const selectSheet = React.useCallback(
    (sheetIndex: number) => {
      const change = resolveXlsxSheetChange({
        activeSheet: activeSheetIndex,
        requestedSheet: sheetIndex,
        sheetCount: sheets?.length,
      })
      if (!change.accepted) return false
      if (change.changed) {
        setActiveSheetIndex(change.sheetIndex)
        onSheetChange?.(change.sheetIndex)
      }
      return true
    },
    [activeSheetIndex, onSheetChange, sheets]
  )

  const activateSheet = React.useCallback(
    (sheetIndex: number) => {
      if (sheetIndex === activeSheetIndex) return
      setActiveSheetIndex(sheetIndex)
      onSheetChange?.(sheetIndex)
    },
    [activeSheetIndex, onSheetChange]
  )

  return {
    activeSheetIndex,
    activeSheet: sheets?.[activeSheetIndex] ?? null,
    sheets,
    isReady: sheets != null,
    reportSource,
    selectSheet,
    activateSheet,
  }
}

export function normalizeInitialSheetIndex(value: number) {
  return Number.isSafeInteger(value) && value > 0 ? value : 0
}

export function clampSheetIndex(value: number, sheetCount: number) {
  if (!Number.isSafeInteger(value) || value < 0) return 0
  return Math.min(value, Math.max(0, sheetCount - 1))
}

import * as React from "react"

const XLSX_MIN_SCALE = 0.25
const XLSX_MAX_SCALE = 5
const XLSX_ZOOM_STEP = 1.2

export function useXlsxScale() {
  const [scale, setScale] = React.useState(1)

  return {
    scale,
    zoomOut: React.useCallback(
      () => setScale((value) => clampXlsxScale(value / XLSX_ZOOM_STEP)),
      []
    ),
    zoomIn: React.useCallback(
      () => setScale((value) => clampXlsxScale(value * XLSX_ZOOM_STEP)),
      []
    ),
    resetZoom: React.useCallback(() => setScale(1), []),
  }
}

export function clampXlsxScale(value: number) {
  return Math.min(XLSX_MAX_SCALE, Math.max(XLSX_MIN_SCALE, value))
}

import type {
  PublicXlsxCellRef,
  XlsxScrollRequest,
} from "./xlsx-viewer-scroll"
import { toInternalCellRef } from "./xlsx-viewer-scroll"

export interface XlsxGridCellRef {
  rowIndex: number
  columnIndex: number
}

export function resolveXlsxActiveCell(
  activeCell: PublicXlsxCellRef | null | undefined,
  sheetIndex: number
): XlsxGridCellRef | null {
  const target = toInternalCellRef(activeCell)
  if (!target || target.sheetIndex !== sheetIndex) return null
  return {
    rowIndex: target.rowIndex,
    columnIndex: target.columnIndex,
  }
}

export function resolveXlsxScrollRequestForSheet(
  scrollRequest: XlsxScrollRequest | null | undefined,
  sheetIndex: number
) {
  return scrollRequest?.sheetIndex === sheetIndex ? scrollRequest : null
}

"use client"

import * as React from "react"

import type { XlsxSource } from "@/lib/xlsx-workbook"
import { XlsxGrid, XlsxGridSkeleton } from "@/components/ui/xlsx-grid"

import {
  resolveXlsxActiveCell,
  resolveXlsxScrollRequestForSheet,
} from "./xlsx-viewer-active-cell"
import type { XlsxCellRef } from "./xlsx-viewer-types"
import type { XlsxScrollRequest } from "./xlsx-viewer-scroll"
import { clampSheetIndex } from "./xlsx-viewer-sheet-state"

export function XlsxViewerSheet({
  sourcePromise,
  activeSheetIndex,
  scale,
  onReportSource,
  activeCell,
  scrollRequest,
  isolateStyles,
  viewportRef,
}: {
  sourcePromise: Promise<XlsxSource>
  activeSheetIndex: number
  scale: number
  onReportSource: (source: XlsxSource) => void
  activeCell?: XlsxCellRef | null
  scrollRequest?: XlsxScrollRequest | null
  isolateStyles: boolean
  viewportRef?: React.RefObject<HTMLDivElement | null>
}) {
  const source = React.use(sourcePromise)

  React.useEffect(() => {
    onReportSource(source)
  }, [source, onReportSource])

  const sheetIndex = clampSheetIndex(activeSheetIndex, source.sheets.length)
  const sheet = source.sheets[sheetIndex]
  const getCell = React.useCallback(
    (rowIndex: number, columnIndex: number) =>
      source.getCell(sheetIndex, rowIndex, columnIndex),
    [source, sheetIndex]
  )

  return (
    <XlsxGrid
      key={sheetIndex}
      rowCount={sheet?.rowCount ?? 0}
      columnCount={sheet?.columnCount ?? 0}
      sheetName={sheet?.name ?? `Sheet ${sheetIndex + 1}`}
      getCell={getCell}
      scale={scale}
      activeCell={resolveXlsxActiveCell(activeCell, sheetIndex)}
      scrollRequest={resolveXlsxScrollRequestForSheet(
        scrollRequest,
        sheetIndex
      )}
      isolateStyles={isolateStyles}
      viewportRef={viewportRef}
    />
  )
}

export function XlsxViewerSheetSkeleton() {
  return <XlsxGridSkeleton />
}
